def verify():
    assert 2 ** 32 / 2 ** 30 == 4 and abs(3.3 / 10e3 * 1e3 - 0.33) < 1e-9 and abs(12 / 48e6 * 1e6 - 0.25) < 1e-12
    assert abs(1e-3 / (48 / 48e6) - 1000) < 1e-6 and abs(0.25 * 5 - 1.25) < 1e-12
    assert abs(2048 * 3.3 / 4096 - 1.65) < 1e-12 and abs(0.25 / 0.01 - 25) < 1e-9 and 115200 // 10 == 11520
    assert abs(2 / 10 + 5 / 20 - 0.45) < 1e-12
    avg = 10 * 0.01 + 0.01 * 0.99; assert abs(avg - 0.1099) < 1e-9 and abs(220 / avg - 2001.8) < 0.1


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
